func:
node.status({fill:'green', shape:'dot', text:'Tables ready'});
node.warn('InfoKiosk tables initialized');
return msg;

msg.payload = {
  success: true,
  database: 'infokiosk',
  result: msg.payload
};
return msg;

const uid = msg.payload.rfid_uid;
if (!uid) {
  msg.payload = {success: false, error: 'Missing rfid_uid'};
  msg.statusCode = 400;
  return [null, msg];
}
msg.rfid_uid = uid;
msg.source = msg.payload.source || 'rfid';
msg.topic = `SELECT id, name, role, rfid_uid, active FROM employees WHERE rfid_uid = '${uid}' LIMIT 1`;
return [msg, null];

if (!msg.payload || msg.payload.length === 0) {
  msg.payload = {success: false, error: 'Unknown RFID card'};
  msg.statusCode = 404;
  return [null, msg];
}
const emp = msg.payload[0];
if (!emp.active) {
  msg.payload = {success: false, error: 'Employee inactive'};
  msg.statusCode = 403;
  return [null, msg];
}
msg.employee = emp;
msg.topic = `SELECT * FROM active_sessions WHERE employee_id = '${emp.id}' LIMIT 1`;
return [msg, null];

const emp = msg.employee;
const hasSession = msg.payload && msg.payload.length > 0;
const now = new Date().toISOString().slice(0,19).replace('T',' ');
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

if (hasSession) {
  // LOGOUT
  msg.isLogout = true;
  msg.session = msg.payload[0];
  msg.topic = `DELETE FROM active_sessions WHERE employee_id = '${emp.id}'`;
} else {
  // LOGIN
  msg.isLogout = false;
  msg.topic = `INSERT INTO active_sessions (employee_id, rfid_uid, login_ts, source) VALUES ('${emp.id}', '${emp.rfid_uid}', '${now}', '${msg.source}')`;
}
msg.eventId = uuid;
msg.eventTs = now;
return msg;

const emp = msg.employee;
const eventType = msg.isLogout ? 'logout' : 'login';
msg.topic = `INSERT INTO attendance_events (id, employee_id, rfid_uid, event_type, ts, source) VALUES ('${msg.eventId}', '${emp.id}', '${emp.rfid_uid}', '${eventType}', '${msg.eventTs}', '${msg.source}')`;
return msg;

if (msg.isLogout) {
  msg.messages = [];
  return [null, msg];
}
const emp = msg.employee;
const now = new Date().toISOString().slice(0,19).replace('T',' ');
msg.topic = `SELECT * FROM employee_messages WHERE enabled = 1 AND (valid_from IS NULL OR valid_from <= '${now}') AND (valid_to IS NULL OR valid_to >= '${now}') AND (target_type = 'all' OR (target_type = 'employee' AND target_value = '${emp.id}') OR (target_type = 'role' AND target_value = '${emp.role}')) ORDER BY priority DESC LIMIT 10`;
return [msg, null];

const emp = msg.employee;
const type = msg.isLogout ? 'logout' : 'login';

msg.wsPayload = {
  type: type + '_success',
  employee: emp,
  messages: msg.messages || []
};

msg.payload = {
  success: true,
  type: type,
  employee: emp,
  messages: msg.messages || []
};
return msg;

let data;
try {
  data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
  return null;
}

switch(data.type) {
  case 'ping':
    msg.payload = JSON.stringify({type: 'pong'});
    return [msg, null];
  case 'request_full_state':
    msg.topic = `SELECT s.*, e.name, e.role FROM active_sessions s JOIN employees e ON s.employee_id = e.id`;
    return [null, msg];
  default:
    return null;
}

msg.payload = JSON.stringify({
  type: 'full_state',
  activeSessions: msg.payload || [],
  timestamp: new Date().toISOString()
});
return msg;

if (msg.wsPayload) {
  msg.payload = JSON.stringify(msg.wsPayload);
} else {
  msg.payload = JSON.stringify(msg.payload);
}
return msg;

const d = msg.payload;
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const vf = d.valid_from ? `'${d.valid_from}'` : 'NULL';
const vt = d.valid_to ? `'${d.valid_to}'` : 'NULL';
const tv = d.target_value ? `'${d.target_value}'` : 'NULL';
msg.topic = `INSERT INTO employee_messages (id, title, body, target_type, target_value, priority, valid_from, valid_to, enabled) VALUES ('${uuid}', '${d.title}', '${d.body || ''}', '${d.target_type || 'all'}', ${tv}, ${d.priority || 2}, ${vf}, ${vt}, ${d.enabled !== false ? 1 : 0})`;
msg.newId = uuid;
return msg;

msg.payload = {success: true, id: msg.newId};
msg.statusCode = 201;
return msg;

const d = msg.payload;
const id = msg.req.params.id;
let sets = [];
if (d.title !== undefined) sets.push(`title='${d.title}'`);
if (d.body !== undefined) sets.push(`body='${d.body}'`);
if (d.target_type !== undefined) sets.push(`target_type='${d.target_type}'`);
if (d.target_value !== undefined) sets.push(`target_value=${d.target_value ? `'${d.target_value}'` : 'NULL'}`);
if (d.priority !== undefined) sets.push(`priority=${d.priority}`);
if (d.valid_from !== undefined) sets.push(`valid_from=${d.valid_from ? `'${d.valid_from}'` : 'NULL'}`);
if (d.valid_to !== undefined) sets.push(`valid_to=${d.valid_to ? `'${d.valid_to}'` : 'NULL'}`);
if (d.enabled !== undefined) sets.push(`enabled=${d.enabled ? 1 : 0}`);
if (sets.length === 0) {
  msg.payload = {success: false, error: 'No fields to update'};
  msg.statusCode = 400;
  return [null, msg];
}
msg.topic = `UPDATE employee_messages SET ${sets.join(', ')} WHERE id = '${id}'`;
return [msg, null];
